#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 100
#define MAX_LEN 1000

typedef struct {
    char digits[MAX_LEN];
    int len;
} BigNum;

// Compare two BigNum: return 1 if a > b, -1 if a < b, 0 if equal
int compare(BigNum *a, BigNum *b) {
    if (a->len != b->len) return a->len > b->len ? 1 : -1;
    for (int i = 0; i < a->len; i++) {
        if (a->digits[i] != b->digits[i])
            return a->digits[i] > b->digits[i] ? 1 : -1;
    }
    return 0;
}

// Copy b to a
void copy(BigNum *a, BigNum *b) {
    a->len = b->len;
    memcpy(a->digits, b->digits, b->len);
}

// Append digit to BigNum (at the end)
void append(BigNum *num, char digit) {
    num->digits[num->len++] = digit;
}

// Remove leading zeros from BigNum (in-place)
void trim_leading_zeros(BigNum *num) {
    int start = 0;
    while (start < num->len && num->digits[start] == '0')
        start++;
    if (start == num->len) {
        // All zeros: keep one zero
        num->digits[0] = '0';
        num->len = 1;
    } else {
        memmove(num->digits, num->digits + start, num->len - start);
        num->len -= start;
    }
}

char grid[MAX_N][MAX_N];
int visited[MAX_N][MAX_N];
int n, m;
BigNum best;

// Directions: right (0,1) and down (1,0)
int dr[] = {0, 1};
int dc[] = {1, 0};

void dfs(int r, int c, BigNum *current) {
    // Update best if current is better
    BigNum trimmed;
    memcpy(&trimmed, current, sizeof(BigNum));
    trim_leading_zeros(&trimmed);
    if (compare(&trimmed, &best) > 0) {
        copy(&best, &trimmed);
    }

    visited[r][c] = 1;
    for (int d = 0; d < 2; d++) {
        int nr = r + dr[d];
        int nc = c + dc[d];
        if (nr < n && nc < m && !visited[nr][nc] && grid[nr][nc] >= '0' && grid[nr][nc] <= '9') {
            append(current, grid[nr][nc]);
            dfs(nr, nc, current);
            current->len--; // backtrack
        }
    }
    visited[r][c] = 0;
}

