// Returns 1 if a > b, -1 if a < b, 0 if equal
int cmpnum(const char *a, const char *b) {
    // strip leading zeros
    while (*a == '0' && *(a+1)) a++;
    while (*b == '0' && *(b+1)) b++;
    int la = strlen(a), lb = strlen(b);
    if (la != lb) return la > lb ? 1 : -1;
    return strcmp(a, b);
}

