/* Compare two non-negative integers written as strings without leading zeros
   except that zero is represented as "0".
   Returns:
   1 if a > b
   0 if equal
  -1 if a < b
*/
int cmp_num(const char *a, const char *b) {
    int la = (int)strlen(a);
    int lb = (int)strlen(b);
    if (la != lb) return (la > lb) ? 1 : -1;
    int c = strcmp(a, b);
    if (c > 0) return 1;
    if (c < 0) return -1;
    return 0;
}

/* Normalize a digit string by suppressing leading zeros. */
void normalize(const char *src, char *dst) {
    while (*src == '0') src++;
    if (*src == '\0') {
        dst[0] = '0';
        dst[1] = '\0';
    } else {
        strcpy(dst, src);
    }
}

