bool isDigitChar(char c) {
    return c >= '0' && c <= '9';
}

string normalizeNumber(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == '0') i++;
    if (i == (int)s.size()) return "0";
    return s.substr(i);
}

bool greaterNumberString(const string& a, const string& b) {
    string x = normalizeNumber(a);
    string y = normalizeNumber(b);
    if (x.size() != y.size()) return x.size() > y.size();
    return x > y;
}

