            while (start < best.length() - 1 && best.charAt(start) == '0') start++;
            System.out.println(best.substring(start));
        }
    }

    static void dfs(int r, int c, StringBuilder sb) {
        updateBest(sb.toString());
        // Try right
        if (c + 1 < C && Character.isDigit(grid[r][c + 1])) {
            sb.append(grid[r][c + 1]);
            dfs(r, c + 1, sb);
            sb.deleteCharAt(sb.length() - 1);
        }
        // Try down
        if (r + 1 < R && Character.isDigit(grid[r + 1][c])) {
            sb.append(grid[r + 1][c]);
            dfs(r + 1, c, sb);
            sb.deleteCharAt(sb.length() - 1);
        }
    }

    static void updateBest(String s) {
        if (isBetter(s, best)) best = s;
    }

    static boolean isBetter(String a, String b) {
        if (a.length() != b.length()) return a.length() > b.length();
        return a.compareTo(b) > 0;
    }
