public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int compareNumbers(String a, String b) {
        String aa = stripLeadingZeros(a);
        String bb = stripLeadingZeros(b);
        if (aa.length() != bb.length()) return Integer.compare(aa.length(), bb.length());
        return aa.compareTo(bb);
    }

    static String stripLeadingZeros(String s) {
        int i = 0;
        while (i < s.length() && s.charAt(i) == '0') i++;
        return i == s.length() ? "0" : s.substring(i);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            int r = Integer.parseInt(first);
            int c = fs.nextInt();
            if (r == 0 && c == 0) break;

            char[][] grid = new char[r][];
            for (int i = 0; i < r; i++) {
                grid[i] = fs.next().toCharArray();
            }

            String best = "0";

            // Horizontal sequences
            for (int i = 0; i < r; i++) {
                int j = 0;
                while (j < c) {
                    if (Character.isDigit(grid[i][j])) {
                        int start = j;
                        while (j < c && Character.isDigit(grid[i][j])) j++;
                        String cur = new String(grid[i], start, j - start);
                        if (compareNumbers(cur, best) > 0) best = cur;
                    } else {
                        j++;
                    }
                }
            }

            // Vertical sequences
            for (int j = 0; j < c; j++) {
                int i = 0;
                while (i < r) {
                    if (Character.isDigit(grid[i][j])) {
                        StringBuilder sb = new StringBuilder();
                        while (i < r && Character.isDigit(grid[i][j])) {
                            sb.append(grid[i][j]);
                            i++;
                        }
                        String cur = sb.toString();
                        if (compareNumbers(cur, best) > 0) best = cur;
                    } else {
                        i++;
                    }
                }
            }

            out.append(stripLeadingZeros(best)).append('\n');
        }

        System.out.print(out.toString());
    }
}

